      ["psyche can hope to become a TRAINER\nof this POKéMON."] = { { 3861278, 43 } },
      ["quickly respond to a threat from any\ndirection with a glare from its upraised\nhead."] = { { 3853785, 74 } },
      ["result in ultrasonic waves that have\nthe power to knock foes flying."] = { { 3916261, 79 } },
      ["return to their quiet mountain retreats\nand go to sleep nestled up against each\nother."] = { { 3856043, 80 } },
      ["serious, its fiery manes flare and blaze\nas it gallops its way up to 150 mph."] = { { 3863898, 84 } },
      ["shake the ground as if lightning bolts\nhad come crashing down."] = { { 3894958, 47 } },
      ["sirens to warn citizens of large-scale\noutbreaks of this POKéMON."] = { { 3864707, 65 } },
      ["small-bodied POKéMON.\nWhen enraged, it releases a horrible\ntoxin from its horn."] = { { 3854835, 105 } },
      ["so one head can always keep watch for\nenemies while the other one sleeps."] = { { 3865029, 38 } },
      ["soon as it spots its prey. The hapless\nprey is tightly grasped by SWELLOW's\nclawed feet, preventing escape."] = { { 3901262, 50 } },
      ["steal the spirits of people when their\neyes burn with a sinister glow in the\ndarkness."] = { { 3905784, 112 } },
      ["steals away to live quietly among\nstalactites and stalagmites deep in\ncaverns."] = { { 3916820, 115 } },
      ["stricken by lightning bolts.\nSome towns use ELECTABUZZ in place of\nlightning rods."] = { { 3872643, 102 } },
      ["striking beauty of the feathers on its\nhead, compelling them to choose PIDGEOT\nas their POKéMON."] = { { 3852828, 86 } },
      ["stumbling and falling to keep up with\nits parent."] = { { 3863674, 118 } },
      ["supposedly only seen in sleepers.\nThis discovery spurred controversy\namong scholars."] = { { 3859473, 88 } },
      ["than a supercomputer.\nThis POKéMON can float in the air by\ntucking in its four legs."] = { { 3919807, 82 } },
      ["that gather around streetlights,\nattracted by the light in the darkness."] = { { 3858555, 41 } },
      ["that it melts anything. However, it\nnever turns its fiery breath on any\nopponent weaker than itself."] = { { 3850802, 59 } },
      ["the cover of dead grass.\nThis POKéMON occasionally roots out\nhot springs."] = { { 3890672, 74 } },
      ["the fact that this POKéMON looks very\nsimilar to a POKé BALL remains a\nmystery."] = { { 3867913, 96 } },
      ["the more brightly the lightbulb at the\ntip of its tail grows."] = { { 3882822, 67 } },
      ["the mountains en masse to the\nfoothills below."] = { { 3863530, 40 } },
      ["the roots of trees. It stays motionless\nas it waits for evolution."] = { { 3903591, 73 } },
      ["the temperature. For that reason, this\nPOKéMON is sometimes used as a\nthermometer."] = { { 3884513, 90 } },
      ["the terrible things it has foreseen in\nthe future."] = { { 3882650, 67 } },
      ["the vast power of nature to protect\nits tiny body."] = { { 3915005, 65 } },
      ["the victim becomes exhausted.\nHowever, it may turn tail if the prey\nstrikes back."] = { { 3898162, 111 } },
      ["their faces to each other when they\nare close because their magnetic noses\nrepel one another."] = { { 3905234, 83 } },
      ["they wreak havoc by stripping the\nleaves off roadside trees for food."] = { { 3899734, 99 } },
      ["things by texture and by taste.\nIt is somewhat put off by sour things."] = { { 3869417, 50 } },
      ["this POKéMON begins swinging its arms\nin circles to recharge itself."] = { { 3894206, 61 } },
      ["this POKéMON is always enveloped in a\nsandstorm while flying."] = { { 3911122, 62 } },
      ["this POKéMON to send signals back and\nforth with others far away."] = { { 3883192, 100 } },
      ["to a rock on the seafloor and catches\napproaching prey using tentacles \nshaped like flower petals."] = { { 3913930, 101 } },
      ["to show their pleasure. Because of this,\ntheir mealtimes are noisy."] = { { 3917223, 80 } },
      ["toxic quills all at once from all over\nits body. It finds swimming somewhat\nchallenging."] = { { 3888894, 98 } },
      ["transformation is to blame for this\nPOKéMON's wildly violent nature."] = { { 3873540, 89 } },
      ["unleash its psychokinetic energy at\nfull power."] = { { 3902171, 42 } },
      ["various UNOWN. Research into this\ntopic is ongoing but nothing is known."] = { { 3886938, 114 } },
      ["vengeance, this POKéMON will appear\nin a swarm and line up beneath the eaves\nof that person's home."] = { { 3915367, 86 } },
      ["voice, this POKéMON makes its listeners\nexperience dreamy wonderment."] = { { 3911856, 74 } },
      ["water at incredible depths. Because of\nthis, this POKéMON's body is unharmed\nby ordinary attacks."] = { { 3918199, 102 } },
      ["when it encounters cold air while it is\nfloating."] = { { 3884705, 76 } },
      ["with its thick and powerful hind legs to\ncharge at the foe at an incredible\nspeed."] = { { 3879246, 114 } },
      ["with other HOPPIP to prepare against\nbeing blown away."] = { { 3884330, 64 } },
      ["within its body steadily builds to reach\nuncontrollable levels."] = { { 3876800, 37 } },
      ["wrapping its tail around rocks or coral\nto prevent being washed away."] = { { 3870920, 91 } },
      ["yawning of this POKéMON creates\nspiraling ocean currents."] = { { 3892525, 38 } },
      ["your pillow and trying to eat your dream\nthrough your nostrils."] = { { 3867212, 77 } },
    },
